"use strict";const themeElements={header:document.getElementById("themeHeader"),icon:document.getElementById("themeIcon"),title:document.getElementById("themeTitle"),description:document.getElementById("themeDescription"),count:document.getElementById("themeCount"),list:document.getElementById("themeDuas"),loading:document.getElementById("themeLoading"),error:document.getElementById("themeError"),cta:document.getElementById("themeCta")};async function initializeThemePage(){const e=document.body.dataset.themeId||new URLSearchParams(window.location.search).get("id");if(e)try{const t=await fetch("/data/duas.json?v=19",{cache:"no-store"});if(!t.ok)throw new Error(`Erreur HTTP ${t.status}`);const n=await t.json(),a=n.categories.find(t=>t.id===e);if(!a)return void showError();renderTheme(a,n.duas.filter(t=>Array.isArray(t.categories)&&t.categories.includes(e)))}catch(e){console.error("Erreur thème :",e),showError()}else showError()}function renderTheme(e,t){themeElements.icon.textContent=e.icon||"✦",themeElements.title.textContent=e.label,themeElements.description.textContent=e.description||"",themeElements.count.textContent=`${t.length} ${t.length>1?"douaas":"douaa"}`,updateThemeSeo(e,t.length),themeElements.list.innerHTML=t.length?t.map(createDuaCard).join(""):'\n      <section class="panel empty-theme-panel">\n        <h2>Aucune douaa disponible</h2>\n        <p>Ce thème sera enrichi prochainement.</p>\n      </section>\n    ',themeElements.loading.classList.add("hidden"),themeElements.header.classList.remove("hidden"),themeElements.cta.classList.remove("hidden")}function updateThemeSeo(e,t){const n=`Douaas ${e.label} — Textes, sources et traductions`,a=`Découvrez ${t} ${t>1?"douaas":"douaa"} pour le thème ${e.label}, avec texte arabe, traduction française et sources.`,o=`https://douaagenerator.fr/themes/${encodeURIComponent(e.slug||e.id)}/`;document.title=n,updateMeta("description",a),updatePropertyMeta("og:title",n),updatePropertyMeta("og:description",a),updatePropertyMeta("og:url",o),updateMeta("twitter:title",n),updateMeta("twitter:description",a),updateCanonical(o),injectJsonLd({"@context":"https://schema.org","@type":"CollectionPage",name:n,description:a,url:o,isPartOf:{"@type":"WebSite",name:"Douaa Generator",url:"https://douaagenerator.fr/"}})}function updateMeta(e,t){let n=document.querySelector(`meta[name="${e}"]`);n||(n=document.createElement("meta"),n.setAttribute("name",e),document.head.appendChild(n)),n.setAttribute("content",t)}function updatePropertyMeta(e,t){let n=document.querySelector(`meta[property="${e}"]`);n||(n=document.createElement("meta"),n.setAttribute("property",e),document.head.appendChild(n)),n.setAttribute("content",t)}function updateCanonical(e){let t=document.querySelector('link[rel="canonical"]');t||(t=document.createElement("link"),t.setAttribute("rel","canonical"),document.head.appendChild(t)),t.setAttribute("href",e)}function injectJsonLd(e){const t=document.createElement("script");t.type="application/ld+json",t.textContent=JSON.stringify(e),document.head.appendChild(t)}function createDuaCard(e){const t=e.title||buildFallbackTitle(e),n=e.meaning||e.context||"";return`\n    <article class="theme-dua-card">\n      <div class="theme-dua-heading">\n        <div>\n          <p class="step-label">${escapeHtml(e.type||"Invocation")}</p>\n          <h2>${escapeHtml(t)}</h2>\n        </div>\n\n        <span class="theme-dua-source">\n          ${escapeHtml(e.source||"")}\n        </span>\n      </div>\n\n      <p class="theme-dua-arabic" dir="rtl" lang="ar">\n        ${escapeHtml(e.arabic||"")}\n      </p>\n\n      <p class="theme-dua-french">\n        ${escapeHtml(e.french||"")}\n      </p>\n\n      ${n?`<p class="theme-dua-explanation">${escapeHtml(n)}</p>`:""}\n\n      <a\n        class="details-link"\n        href="/douaas/${encodeURIComponent(e.slug||e.id)}/"\n      >\n        Voir la fiche complète\n        <span aria-hidden="true">→</span>\n      </a>\n    </article>\n  `}function buildFallbackTitle(e){return`Invocation${e.source?` — ${e.source}`:""}`}function showError(){themeElements.loading.classList.add("hidden"),themeElements.header.classList.add("hidden"),themeElements.error.classList.remove("hidden")}function escapeHtml(e){return String(e??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}document.addEventListener("DOMContentLoaded",initializeThemePage);